import React, { useState } from 'react';
import { collection, doc, setDoc } from 'firebase/firestore';
import { db } from '../firebase';
import './submitScore.css';

const players = [
  'Jack', 'Linyi', 'JoeZ', 'Elaine', 'JoeS', 'Chloe', 'TJin', 'Eldon'
];

export default function SubmitScore() {
  const [scores, setScores] = useState(
    players.map(player => ({ player, score: '', active: true }))
  );
  const [submitted, setSubmitted] = useState(false);
  const [showModal, setShowModal] = useState(false);

  const handleScoreChange = (index, value) => {
    const updated = [...scores];
    updated[index].score = value; // just store raw string
    setScores(updated);
  };
  

  const handleRemovePlayer = (index) => {
    const updated = [...scores];
    updated.splice(index, 1);
    setScores(updated);
  };

  const handleSubmit = () => {
    setShowModal(true);
  };

  const confirmSubmit = async () => {
    const filteredScores = scores
    .filter(p => p.score !== '' && p.active)
    .map(({ player, score }) => {
      const parsed = parseInt(score, 10);
      const clamped = isNaN(parsed) ? 2 : Math.max(2, Math.min(parsed, 16));
      return { player, score: clamped };
    });

    if (filteredScores.length === 0) {
      setShowModal(false);
      return;
    }

    const newSubmission = {
      id: `submission_${Date.now()}`,
      timestamp: Date.now(),
      scores: filteredScores
    };

    try {
      const docRef = doc(db, 'pendingSubmissions', newSubmission.id);
      await setDoc(docRef, newSubmission);
      setSubmitted(true);
      setScores(players.map(player => ({ player, score: '', active: true })));
      setShowModal(false);
    } catch (error) {
      console.error('Error adding document: ', error);
      alert('Failed to submit scores. Please try again.');
      setShowModal(false);
    }
  };

  const cancelSubmit = () => {
    setShowModal(false);
  };

  return (
    <div className="submit-container">
      <h2>Submit Scores</h2>
      {submitted && <div className="success-popup">Score submitted for approval!</div>}
      {scores.map((entry, idx) => (
        <div key={idx} className="player-row">
          <span className="player-name">{entry.player}</span>
          <input
            type="number"
            value={entry.score}
            onChange={(e) => handleScoreChange(idx, e.target.value)}
            placeholder="Enter score"
            min={2}
            max={16}
          />
          <button className="remove-button" onClick={() => handleRemovePlayer(idx)}>Remove</button>
        </div>
      ))}
      <button className="submit-button" onClick={handleSubmit}>Submit All</button>

      {showModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Confirm Submission</h3>
            <ul>
              {scores
                .filter(p => p.score !== '' && p.active)
                .map((entry, idx) => (
                  <li key={idx}>{entry.player}: {entry.score}</li>
                ))}
            </ul>
            <div className="modal-actions">
              <button onClick={confirmSubmit} className="submit-button">Confirm</button>
              <button onClick={cancelSubmit} className="remove-button">Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
