import React, { useState, useEffect } from 'react';
import { getFirestore, collection, getDocs, deleteDoc, doc, updateDoc, getDoc,addDoc, setDoc,onSnapshot } from 'firebase/firestore';
import { db } from '../firebase';
import './approval.css';

const ADMIN_PASSWORD = 'Elaine1234*';

export default function ApprovalPage() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [passwordInput, setPasswordInput] = useState('');
  const [pendingSubmissions, setPendingSubmissions] = useState([]);
  const [feedback, setFeedback] = useState('');

  //const db = getFirestore();

  useEffect(() => {
    const auth = sessionStorage.getItem('adminAuthenticated');
    if (auth === 'true') {
      setIsAuthenticated(true);
    }
  }, []);

  useEffect(() => {
    const auth = sessionStorage.getItem('adminAuthenticated');
    if (auth === 'true') {
      setIsAuthenticated(true);
      const unsubscribe = onSnapshot(collection(db, 'pendingSubmissions'), (snapshot) => {
        const data = snapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setPendingSubmissions(data);
      });
  
      // Cleanup listener on unmount
      return () => unsubscribe();
    }
  }, []);
  

  const handlePasswordSubmit = async (e) => {
    e.preventDefault();
    if (passwordInput === ADMIN_PASSWORD) {
      sessionStorage.setItem('adminAuthenticated', 'true');
      setIsAuthenticated(true);
      setPasswordInput('');
      setFeedback('');
    } else {
      setFeedback('Incorrect password. Please try again.');
    }
  };

  const approveSubmission = async (submissionId) => {
    const submission = pendingSubmissions.find(s => s.id === submissionId);
    if (!submission) return;
  
    try {
      const mainScoresRef = collection(db, 'mainScores');
      const historyRef = collection(db, 'scoreHistory');  // <-- new collection
  
      for (const { player, score } of submission.scores) {
        const playerRef = doc(db, 'mainScores', player);
        const playerSnap = await getDoc(playerRef);
  
        if (playerSnap.exists()) {
          const data = playerSnap.data();
          await updateDoc(playerRef, {
            totalScore: (data.totalScore || 0) + score,
            played: (data.played || 0) + 1
          });
        } else {
          await setDoc(playerRef, {
            totalScore: score,
            played: 1
          });
        }
      }
  
      // Add approved submission record to scoreHistory
      await addDoc(historyRef, {
        timestamp: Date.now(),
        scores: submission.scores,
        submissionId: submission.id,
        approvedAt: new Date().toISOString()
        // optionally add: approvedBy: 'admin'
      });
  
      await deleteDoc(doc(db, 'pendingSubmissions', submissionId));
      setPendingSubmissions(prev => prev.filter(s => s.id !== submissionId));
      setFeedback('Submission approved, scores updated, and history recorded.');
    } catch (error) {
      console.error('Approval failed:', error);
      setFeedback('Failed to approve submission.');
    }
  };
  
  

  const rejectSubmission = async (submissionId) => {
    try {

        const ref = doc(db, "pendingSubmissions", "submission_1750627118119");
        const snap = await getDoc(ref);
      await deleteDoc(doc(db, 'pendingSubmissions', submissionId));
      console.log('Submission deleted');

      setFeedback('Submission rejected');

     

    } catch (error) {
      console.error('Rejection failed:', error);
      setFeedback('Failed to reject submission.');
    }
  };

  const testFetch = async () => {
    const snapshot = await getDocs(collection(db, 'pendingSubmissions'));
    snapshot.docs.forEach(docSnap => {
      console.log('Doc ID:', docSnap.id, 'Data:', docSnap.data());
    });
  };
  testFetch();
  

  if (!isAuthenticated) {
    return (
      <div className="approval-container">
        <h2>Admin Login</h2>
        <form onSubmit={handlePasswordSubmit} className="approval-form">
          <input
            type="password"
            value={passwordInput}
            onChange={(e) => setPasswordInput(e.target.value)}
            placeholder="Enter admin password"
            className="approval-input"
          />
          <button type="submit" className="submit-button">Submit</button>
        </form>
        {feedback && <p className="approval-feedback">{feedback}</p>}
      </div>
    );
  }

  return (
    <div className="approval-container">
      <h2>Pending Score Submissions</h2>
      {feedback && <p className="approval-feedback">{feedback}</p>}
      {pendingSubmissions.length === 0 ? (
        <p className="approval-empty">No pending submissions.</p>
      ) : (
        pendingSubmissions.map((submission) => (
          <div key={submission.id} className="approval-card">
            <p><strong>Submitted:</strong> {new Date(submission.timestamp).toLocaleString()}</p>
            <table className="approval-table">
              <thead>
                <tr>
                  <th>Player</th>
                  <th>Score</th>
                </tr>
              </thead>
              <tbody>
                {submission.scores.map(({ player, score }, idx) => (
                  <tr key={idx}>
                    <td>{player}</td>
                    <td>{score}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div className="approval-actions">
              <button
                onClick={() => approveSubmission(submission.id)}
                className="submit-button"
              >
                Approve All
              </button>
              <button
                onClick={() => rejectSubmission(submission.id)}
                className="remove-button"
              >
                Reject All
              </button>
            </div>
          </div>
        ))
      )}
    </div>
  );
}
