import * as React from 'react';
import { useEffect, useState } from 'react';
import { db } from '../firebase';
import {
  collection,
  query,
  onSnapshot,
  doc,
  getDoc
} from 'firebase/firestore';

import Box from '@mui/material/Box';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TablePagination from '@mui/material/TablePagination';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import Typography from '@mui/material/Typography';

import JackAvatar from '../images/Jack.gif';
import LinyiAvatar from '../images/Linyi.gif';
import JoeZAvatar from '../images/JoeZ.gif';
import ElaineAvatar from '../images/Elaine.gif';
import JoeSAvatar from '../images/JoeS.gif';
import ChloeAvatar from '../images/Season4/Chloe.gif';
import TJinAvatar from '../images/Season4/TJin.gif';
import EldonAvatar from '../images/Eldon.gif';

const avatarMap = {
  Jack: JackAvatar,
  Linyi: LinyiAvatar,
  JoeZ: JoeZAvatar,
  Elaine: ElaineAvatar,
  JoeS: JoeSAvatar,
  Chloe: ChloeAvatar,
  TJin: TJinAvatar,
  Eldon: EldonAvatar
};

export default function Score() {
  const [scores, setScores] = useState([]);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [lastUpdated, setLastUpdated] = useState(null);

  useEffect(() => {
    const q = query(collection(db, 'mainScores'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const scoreData = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          name: doc.id,
          totalScore: data.totalScore || 0,
          played: data.played || 0,
          avgScore: data.played > 0 ? (data.totalScore / data.played).toFixed(2) : '0.00',
          avatar: avatarMap[doc.id] || null
        };
      });
      setScores(scoreData);
    }, (error) => {
      console.error("Failed to get live updates:", error);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const fetchLastUpdate = async () => {
      try {
        const metaDoc = await getDoc(doc(db, 'config', 'lastUpdate'));
        if (metaDoc.exists()) {
          const ts = metaDoc.data()?.timestamp;
          setLastUpdated(new Date(ts).toLocaleString());
        }
      } catch (err) {
        console.error("Failed to fetch last update time:", err);
      }
    };
  
    fetchLastUpdate();
  }, [scores]); // 👈 now refetches whenever scores change
  

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <Box sx={{ width: '100%' }}>
      <Paper sx={{ width: '100%', mb: 2, p: 2 }}>
        <Typography variant="subtitle1" sx={{ mb: 1 }}>
          Rules: 2–10 = 2–10; J,Q,K = 11,12,13; A = 14; A+(庄上) = 15; 大光(庄上) = 16；大光(庄下) = 15；
        </Typography>
        {lastUpdated && (
          <Typography variant="caption" color="text.secondary" sx={{ mb: 2, display: 'block' }}>
            Last updated: {lastUpdated}
          </Typography>
        )}
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Player</TableCell>
                <TableCell align="right">Total Points</TableCell>
                <TableCell align="right"># Played</TableCell>
                <TableCell align="right">Avg Score</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {scores
                .sort((a, b) => b.avgScore - a.avgScore)
                .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                .map((row, idx) => (
                  <TableRow key={idx}>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        {row.avatar && (
                          <img
                            src={row.avatar}
                            alt={`${row.name}'s avatar`}
                            style={{ width: 32, height: 32, borderRadius: '50%', marginRight: 8 }}
                          />
                        )}
                        {row.name}
                      </Box>
                    </TableCell>
                    <TableCell align="right">{row.totalScore}</TableCell>
                    <TableCell align="right">{row.played}</TableCell>
                    <TableCell align="right">{row.avgScore}</TableCell>
                  </TableRow>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
        <TablePagination
          rowsPerPageOptions={[5, 10, 25]}
          component="div"
          count={scores.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        />
      </Paper>
    </Box>
  );
}
